head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil51110";
scwin.form = null;
scwin.saveYn = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — listProcsStatCd, isOk

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.saveYn = '' + dma_dataList.get("save_yn") + '';
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil51110.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String(((String(dma_basicComInfo.get("listTpClssCd")) === "02") ? "상장법인" : "심사진행법인")); } },
        { childId: "__rb1", attr: "label", fn: function () { return String(dma_basicComInfo.get("comNm")) + "(" + String(dma_basicComInfo.get("isurCd")) + ")"; } },
        { childId: "__rb2", attr: "label", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["usrId"] ?? "") + "/" + String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["corpUsrNm"] ?? ""); } },
        { childId: "__rb3", attr: "label", fn: function () { return String(dma_basicComInfo.get("mktTpNm")); } },
        { childId: "__rb4", attr: "label", fn: function () { return String(dma_basicComInfo.get("secugrpNm")); } },
        { childId: "__rb5", attr: "label", fn: function () { return String(((String(dma_basicComInfo.get("listTpClssCd")) === "02") ? "우회상장보고서 제출일" : "예비심사청구서 제출일")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        const v = a.fn();
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_42", fn: function(){ return ((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '02'); } }, { id: "c_otherwise_47", fn: function(){ return (!(((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '02'))); } }, { id: "if_listTpClssCd_3", fn: function(){ return ((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '02'); } }, { id: "tr_86", fn: function(){ return ((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '02'); } }, { id: "if_listTpClssCd_4", fn: function(){ return ((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '06' || (dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '07'); } }, { id: "tr_93", fn: function(){ return ((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '06' || (dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '07'); } }, { id: "c_when_105", fn: function(){ return ((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '02'); } }, { id: "c_when_114", fn: function(){ return ((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '06'); } }, { id: "c_when_123", fn: function(){ return ((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '07'); } }, { id: "btn_doSave", fn: function(){ return ((dma_pageContext.get("listProcsStatCd") ?? "") === '' || (dma_pageContext.get("listProcsStatCd") ?? "") === '30' || (dma_pageContext.get("listProcsStatCd") ?? "") === '35'|| (dma_pageContext.get("listProcsStatCd") ?? "") === '37'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_listTpClssCd", fn: function () { return String((dma_pageContext.get("listTpClssCd") ?? "")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.onload();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil51110.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 2건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId","corpUsrNm"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil51110' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

