 */
scwin.prelistPageSearch = async function () {
    scwin.form.action = '/listInvstg/listPrelmInvstg.do';
    $c.util.getComponent('dma_doSaveReq').set('method', "listPrelmInvstgList");
    $c.util.getComponent('dma_doSaveReq').set('page', "list");
    await scwin.tx_fn_PrelistPageSearch();
};
